#!/usr/bin/env python3
import json
import os
import sys

coverage_file = sys.argv[1] if len(sys.argv) > 1 else "coverage/coverage-summary.json"
output_file = sys.argv[2] if len(sys.argv) > 2 else "/tmp/coverage_comment.md"

if not os.path.exists(coverage_file):
    print(f"Coverage file not found: {coverage_file}", file=sys.stderr)
    sys.exit(1)

with open(coverage_file, "r", encoding="utf-8") as f:
    data = json.load(f)

total = data.get("total", {})

def get_metric(metric_name):
    m = total.get(metric_name, {})
    pct = m.get("pct", 0)
    covered = m.get("covered", 0)
    tot = m.get("total", 0)
    return pct, covered, tot

lines_pct, lines_cov, lines_tot = get_metric("lines")
stmts_pct, stmts_cov, stmts_tot = get_metric("statements")
funcs_pct, funcs_cov, funcs_tot = get_metric("functions")
branch_pct, branch_cov, branch_tot = get_metric("branches")

def get_badge(pct):
    if pct >= 100:
        return "🟢 100%"
    elif pct >= 90:
        return f"🟡 {pct:.1f}%"
    else:
        return f"🔴 {pct:.1f}%"

all_100 = (lines_pct == 100 and stmts_pct == 100 and funcs_pct == 100 and branch_pct == 100)
overall_status = "✅ **All 100% Thresholds Met**" if all_100 else "⚠️ **Coverage Threshold Warning**"

# File-by-file summary
file_rows = []
for file_path, metrics in data.items():
    if file_path == "total":
        continue
    # Shorten path relative to repository
    rel_path = file_path
    if "/quizapp/" in file_path:
        rel_path = file_path.split("/quizapp/", 1)[1]
    
    f_lines = metrics.get("lines", {}).get("pct", 0)
    f_branch = metrics.get("branches", {}).get("pct", 0)
    f_funcs = metrics.get("functions", {}).get("pct", 0)
    f_stmts = metrics.get("statements", {}).get("pct", 0)
    
    file_rows.append(f"| `{rel_path}` | {get_badge(f_lines)} | {get_badge(f_branch)} | {get_badge(f_funcs)} | {get_badge(f_stmts)} |")

files_table = "\n".join(file_rows)

markdown = f"""<!-- vitest-coverage-report -->
### 📊 Vitest Test Coverage Summary

{overall_status}

| Metric | Coverage | Progress | Target |
| :--- | :---: | :---: | :---: |
| **Lines** | {get_badge(lines_pct)} | `{lines_cov}/{lines_tot}` | 100% |
| **Statements** | {get_badge(stmts_pct)} | `{stmts_cov}/{stmts_tot}` | 100% |
| **Functions** | {get_badge(funcs_pct)} | `{funcs_cov}/{funcs_tot}` | 100% |
| **Branches** | {get_badge(branch_pct)} | `{branch_cov}/{branch_tot}` | 100% |

<details>
<summary><b>📁 File-by-File Coverage Breakdown ({len(file_rows)} files)</b></summary>

| File | Lines | Branches | Functions | Statements |
| :--- | :---: | :---: | :---: | :---: |
{files_table}

</details>

*Automated test report generated by GitHub Actions CI.*
"""

with open(output_file, "w", encoding="utf-8") as out:
    out.write(markdown)

print(f"Coverage comment written to {output_file}")
